CREATE TABLE IF NOT EXISTS studio_projects (id TEXT PRIMARY KEY, account_id INTEGER NOT NULL, name TEXT NOT NULL, storage_mode TEXT NOT NULL DEFAULT 'cloud', permission_mode TEXT NOT NULL DEFAULT 'reads', status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS studio_files (project_id TEXT NOT NULL, path TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, r2_key TEXT, content_type TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(project_id, path));
CREATE TABLE IF NOT EXISTS studio_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER NOT NULL, project_id TEXT, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS studio_plugins (id TEXT PRIMARY KEY, account_id INTEGER NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, endpoint TEXT, manifest TEXT NOT NULL DEFAULT '{}', enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS studio_deployments (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_studio_audit_account ON studio_audit(account_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_studio_deployments_project ON studio_deployments(project_id, id DESC);
